/**
 * Samhälle & institutioner → Juridik & rättsväsende → Brott & straff, 1411–1417 (0.31): the elements of
 * a crime, intent and negligence, attempt and complicity, fines and prison, sentencing and sanctions,
 * general and individual prevention, and common offences. Abstract legal ideas are shown as small
 * symbolic scenes (the act, the law book with a paragraph sign, prison bars, coins, a balance, a
 * calendar); people never carry real brands or uniforms of a real agency, and no text names a word.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, type Svg } from './kit';
import { type Build } from './figures';
import { HL, arm, heart, shield, phone, T } from './people';
import { P as F, type Mood, greyed, coin } from './blindFix';
import { checkIcon } from './labelIcons';
import { cal, clock } from './time';
import { win, door, tree, house, car, fence, key } from './homeKit';

// ── Geometry and figures ─────────────────────────────────────────────
const RED = '#e8302c';
const f1 = (n: number) => n.toFixed(1);
const ground = line('M4 112 L116 112', C.grey2, 2);
const PC = ['#e85a5a', '#5aa7e8', '#7ac06a', '#f2c14e', '#a585d0', '#f28a2e'];
/** Head and shoulder positions of a standing figure (figures.ts) at x with height factor h. */
const geo = (x: number, h = 1) => { const s = 0.84 * h, ty = 112 - 49 * s; return { s, hy: ty - 56 * s, hr: 10 * s, sy: ty - 38 * s, sl: x - 13 * s, sr: x + 13 * s }; };
const hnd = (x: number, y: number, r = 3) => circle(x, y, r, C.skin, C.ink, 1.2);
/** An arm that starts at the shoulder (side −1 = picture-left, 1 = picture-right) and ends in a hand at (tx, ty). */
const reach = (x: number, h: number, side: -1 | 1, tx: number, ty: number) => { const q = geo(x, h); return all(arm(side < 0 ? q.sl : q.sr, q.sy, tx, ty), hnd(tx, ty, 3 * Math.max(0.7, h))); };
const fig = (x: number, top: string, mood: Mood = 'smile', more: Partial<Build> = {}) => F({ x, top, mood, ...more });
/** Small head-and-shoulders person (for crowds). */
const mini = (x: number, y: number, col: string, mood: 'smile' | 'frown' | 'flat' | 'shock' = 'smile', s = 1, long = false) => g(`translate(${x} ${y}) scale(${s})`, long ? path('M-8 -6 C-9 6 9 6 8 -6 Z', C.hair, null) : '', path('M-10 16 C-10 4 10 4 10 16 Z', col, C.ink, 1.4), circle(0, -6, 7.5, C.skin, C.ink, 1.4), path('M-7.5 -8 C-7.5 -16 7.5 -16 7.5 -8 C4 -11 -4 -11 -7.5 -8 Z', C.hair, null),
  circle(-2.6, -6, 1, C.ink, null), circle(2.6, -6, 1, C.ink, null),
  mood === 'smile' ? path('M-2.6 -2.6 Q0 -0.6 2.6 -2.6', 'none', C.ink, 1.1) : mood === 'flat' ? line('M-2.4 -2 L2.4 -2', C.ink, 1.1) : mood === 'shock' ? ellipse(0, -2, 1.4, 1.8, '#c84a4a', C.ink, 0.8) : path('M-2.6 -1.4 Q0 -3.4 2.6 -1.4', 'none', C.ink, 1.1));
/** A dark hood around the face of a standing figure (the person who commits the crime). */
const hood = (x: number, h = 1) => { const k = geo(x, h), rx = k.hr * 1.32, ry = k.hr * 1.42, cy = k.hy - k.hr * 0.12, irx = k.hr * 0.8, iry = k.hr * 0.86, icy = k.hy + k.hr * 0.18; return `<path d="M${f1(x - rx)} ${f1(cy)} a${f1(rx)} ${f1(ry)} 0 1 0 ${f1(2 * rx)} 0 a${f1(rx)} ${f1(ry)} 0 1 0 ${f1(-2 * rx)} 0 Z M${f1(x - irx)} ${f1(icy)} a${f1(irx)} ${f1(iry)} 0 1 0 ${f1(2 * irx)} 0 a${f1(irx)} ${f1(iry)} 0 1 0 ${f1(-2 * irx)} 0 Z" fill="${C.dark}" fill-rule="evenodd" stroke="${C.ink}" stroke-width="1.2"/>`; };
const crook = (x: number, mood: Mood = 'angry', h = 0.8, more: Partial<Build> = {}) => all(fig(x, C.dark, mood, { h, bottom: C.black, ...more }), hood(x, h));
/** Police officer: navy uniform and a flat cap with a small badge. */
const cap = (x: number, h = 1) => { const k = geo(x, h); return all(path(`M${f1(x - k.hr * 1.1)} ${f1(k.hy - k.hr * 0.55)} L${f1(x - k.hr * 1.2)} ${f1(k.hy - k.hr * 1.3)} L${f1(x + k.hr * 1.2)} ${f1(k.hy - k.hr * 1.3)} L${f1(x + k.hr * 1.1)} ${f1(k.hy - k.hr * 0.55)} Z`, C.navy, C.ink, 1.2), line(`M${f1(x - k.hr * 1.2)} ${f1(k.hy - k.hr * 0.5)} L${f1(x + k.hr * 1.3)} ${f1(k.hy - k.hr * 0.5)}`, C.black, k.hr * 0.25), circle(x, k.hy - k.hr * 0.95, k.hr * 0.22, C.gold, null)); };
const cop = (x: number, mood: Mood = 'calm', h = 0.8, more: Partial<Build> = {}) => all(fig(x, C.navy, mood, { h, bottom: C.navy, ...more }), cap(x, h));
/** Speech bubble centred on (cx, cy) whose tail points to (tx, ty). */
const say = (cx: number, cy: number, w: number, h: number, tx: number, ty: number, inner: Svg = '', fill: string = C.white) => {
  const L = cx - w / 2, R = cx + w / 2, Tp = cy - h / 2, B = cy + h / 2;
  let a: number[], b: number[], a2: number[], b2: number[];
  if (tx < L || tx > R) { const e = tx < L ? L : R, inw = tx < L ? 1.6 : -1.6, by = Math.max(Tp + 6, Math.min(B - 6, ty)); a = [e, by - 4.5]; b = [e, by + 4.5]; a2 = [e + inw, by - 3.6]; b2 = [e + inw, by + 3.6]; }
  else { const e = ty > cy ? B : Tp, inw = ty > cy ? -1.6 : 1.6, bx = Math.max(L + 7, Math.min(R - 7, tx)); a = [bx - 5, e]; b = [bx + 5, e]; a2 = [bx - 4, e + inw]; b2 = [bx + 4, e + inw]; }
  return all(path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, C.ink, 1.5), rect(L, Tp, w, h, fill, 6, C.ink, 1.5), path(`M${a2[0]} ${a2[1]} L${tx} ${ty} L${b2[0]} ${b2[1]} Z`, fill, null), inner);
};
/** Bubble beside the head of the figure at x (side 1 = right of the head, −1 = left); f draws the content at the bubble centre. */
const sb = (x: number, h: number, side: 1 | -1, w: number, hh: number, f: (cx: number, cy: number) => Svg, dx = 0, dy = 0) => { const k = geo(x, h), cx = x + side * (k.hr + 6 + w / 2) + dx, cy = k.hy - 8 + dy; return say(cx, cy, w, hh, x + side * (k.hr + 1), k.hy, f(cx, cy)); };
/** Thought cloud beside a head (side as in sb). */
const tb = (x: number, h: number, side: 1 | -1, w: number, f: (cx: number, cy: number) => Svg, dx = 0, dy = 0, hh = 24) => { const k = geo(x, h), cx = x + side * (k.hr + 8 + w / 2) + dx, cy = k.hy - 6 + dy; return all(ellipse(cx, cy, w / 2, hh / 2, C.white, C.ink, 1.6), circle(x + side * (k.hr + 5), k.hy - 4, 2.4, C.white, C.ink, 1.1), circle(x + side * (k.hr + 2), k.hy + 1, 1.6, C.white, C.ink, 1), f(cx, cy)); };

// ── Marks ────────────────────────────────────────────────────────────
const check = (x: number, y: number, s = 1, col: string = C.green) => checkIcon(x, y, s, col);
const cross = (x: number, y: number, s = 1, col: string = RED) => line(`M${x - 5 * s} ${y - 5 * s} L${x + 5 * s} ${y + 5 * s} M${x + 5 * s} ${y - 5 * s} L${x - 5 * s} ${y + 5 * s}`, col, 2.4 * s);
const okB = (x: number, y: number, r = 8) => all(circle(x, y, r, C.green, C.ink, 1.2), path(`M${f1(x - r * 0.45)} ${y} L${f1(x - r * 0.1)} ${f1(y + r * 0.35)} L${f1(x + r * 0.5)} ${f1(y - r * 0.4)}`, 'none', C.white, r * 0.22));
const noB = (x: number, y: number, r = 8) => all(circle(x, y, r, RED, C.ink, 1.2), line(`M${f1(x - r * 0.4)} ${f1(y - r * 0.4)} L${f1(x + r * 0.4)} ${f1(y + r * 0.4)} M${f1(x + r * 0.4)} ${f1(y - r * 0.4)} L${f1(x - r * 0.4)} ${f1(y + r * 0.4)}`, C.white, r * 0.22));
const palm = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, ...[-4.6, -1.6, 1.4, 4.4].map((d, i) => rect(d - 1.3, -9 + Math.abs(i - 1.5) * 1.2, 2.6, 9, C.skin, 1.3, C.ink, 0.9)), path('M-5.5 -1 L5.5 -1 L5 5 C4 8 -4 8 -5 5 Z', C.skin, C.ink, 1), path('M-5.4 1 L-9 -3 C-10 -4 -11 -2 -10 -1 L-5 5', C.skin, C.ink, 1));
const fist = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-6, -5, 12, 10, C.skin, 3, C.ink, 1.2), line('M-2 -5 L-2 0 M2 -5 L2 0', C.ink, 0.8));
const upA = (x: number, y: number, col: string = C.green, l = 14) => arrow(x, y + l / 2, x, y - l / 2, col, 2.6);
const downA = (x: number, y: number, col: string = RED, l = 14) => arrow(x, y - l / 2, x, y + l / 2, col, 2.6);
const dash = (d: string, col: string = HL, w = 1.6, da = '3 3') => `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-dasharray="${da}" stroke-linecap="round"/>`;
const bang = (x: number, y: number, s = 1, col: string = RED) => all(path(`M${x - 2 * s} ${y - 9 * s} L${x + 2 * s} ${y - 9 * s} L${x + 1 * s} ${y + 2 * s} L${x - 1 * s} ${y + 2 * s} Z`, col, null), circle(x, y + 5 * s, 1.6 * s, col, null));
const qm = (x: number, y: number, size = 14, col: string = C.navy) => T(x, y, '?', size, col);
/** Paragraph sign – the mark of a law. */
const sect = (x: number, y: number, size = 14, col: string = C.navy) => T(x, y + size * 0.35, '§', size, col);
const stars = (x: number, y: number, s = 1) => all(sparkle(x, y, 3 * s, C.yellow), sparkle(x + 7 * s, y - 4 * s, 2.4 * s, C.yellow), sparkle(x - 6 * s, y - 5 * s, 2 * s, C.yellow));
const waves = (x: number, y: number, s = 1, col: string = HL) => all(path(`M${x} ${y - 5 * s} Q${x + 4 * s} ${y} ${x} ${y + 5 * s}`, 'none', col, 1.6), path(`M${x + 4 * s} ${y - 9 * s} Q${x + 11 * s} ${y} ${x + 4 * s} ${y + 9 * s}`, 'none', col, 1.6));

// ── Things ───────────────────────────────────────────────────────────
const paper = (x: number, y: number, s = 1, mark: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-9, -12, 18, 24, C.white, 1.5, C.ink, 1.2), line('M-5 -6 L5 -6 M-5 -1 L5 -1 M-5 4 L2 4', C.grey, 1.2), mark);
/** The law book: a thick navy book with a paragraph sign on the cover. */
const lawBook = (x: number, y: number, s = 1, col: string = C.navy) => g(`translate(${x} ${y}) scale(${s})`, rect(-12, -16, 24, 32, col, 2, C.ink, 1.4), rect(-12, -16, 4, 32, 'rgba(0,0,0,0.25)', 1, null), rect(10, -14, 3, 28, C.white, 1, C.ink, 0.8), sect(2, 0, 16, C.gold));
/** A barred window (cell window), top-left at x, y. */
const barWin = (x: number, y: number, w = 18, h = 18, bg: string = '#2f3240') => all(rect(x, y, w, h, bg, 1, C.ink, 1.4), ...Array.from({ length: 3 }, (_, i) => line(`M${f1(x + (w * (i + 1)) / 4)} ${y} L${f1(x + (w * (i + 1)) / 4)} ${y + h}`, C.silver, 1.6)));
/** Prison: a grey building with barred windows behind a high wall, and a watchtower (bottom centre x, y). */
const prison = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-30, -46, 60, 34, '#b9bcc2', 1, C.ink, 1.6), ...[-22, -6, 10].map((d) => barWin(d, -40, 12, 12)), rect(-42, -18, 84, 18, '#9a9ea7', 1, C.ink, 1.8), line('M-42 -18 L42 -18', C.ink, 1), ...[-36, -24, -12, 0, 12, 24, 36].map((d) => line(`M${d} -18 L${d} -22`, C.ink, 1)), line('M-42 -22 L42 -22', C.ink, 0.8),
  rect(30, -54, 10, 36, '#9a9ea7', 1, C.ink, 1.4), path('M27 -54 L35 -62 L43 -54 Z', C.dark, C.ink, 1.2), rect(32, -52, 6, 4, '#fff3b0', 0.5, C.ink, 0.8));
/** Cell seen from inside: wall, barred window, a narrow bed. */
const cell = (inner: Svg = '') => all(rect(4, 6, 112, 106, '#d9d6cf', 2, C.ink, 1.8), rect(4, 92, 112, 20, '#bdb8ae', 0, null), barWin(46, 18, 28, 22, '#9fd0f0'), rect(8, 82, 44, 8, '#8a8f99', 1, C.ink, 1.4), rect(8, 76, 14, 7, C.white, 3, C.ink, 1.2), inner);
/** Vertical bars in front of a whole scene (we look into the cell). */
const barsFront = (x1: number, x2: number, y1 = 8, y2 = 112, n = 6) => all(...Array.from({ length: n }, (_, i) => line(`M${f1(x1 + ((x2 - x1) * i) / (n - 1))} ${y1} L${f1(x1 + ((x2 - x1) * i) / (n - 1))} ${y2}`, '#5b5f69', 2.6)), line(`M${x1} ${y1} L${x2} ${y1}`, '#5b5f69', 3));
const coins = (x: number, y: number, n: number, r = 6) => all(...Array.from({ length: n }, (_, i) => all(ellipse(x, y - i * 3, r, r * 0.42, C.gold, C.ink, 1), ellipse(x, y - i * 3 - 0.6, r * 0.6, r * 0.22, 'none', '#b88a20', 0.7))));
const bill = (x: number, y: number, s = 1, rot = 0) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, rect(-11, -6, 22, 12, '#a8d8a8', 1.5, C.ink, 1.1), circle(0, 0, 3.4, 'none', '#4f9d69', 1.1));
const knife = (x: number, y: number, s = 1, rot = 0) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, path('M0 -2 L18 -2 C22 -2 24 0 24 0 L0 4 Z', C.silver, C.ink, 1.1), rect(-10, -3, 10, 7, C.dark, 2, C.ink, 1));
const handbag = (x: number, y: number, s = 1, col: string = C.red) => g(`translate(${x} ${y}) scale(${s})`, path('M-9 -4 L9 -4 L11 10 L-11 10 Z', col, C.ink, 1.3), path('M-5 -4 C-5 -12 5 -12 5 -4', 'none', C.ink, 1.4));
const bottle = (x: number, y: number, s = 1, col = '#7a4a1e') => g(`translate(${x} ${y}) scale(${s})`, path('M-4 0 L-4 -14 C-4 -17 -2 -18 -2 -21 L-2 -26 L2 -26 L2 -21 C2 -18 4 -17 4 -14 L4 0 Z', col, C.ink, 1.1), rect(-4, -12, 8, 6, C.yellow, 0.5, null));
const bike = (x: number, y: number, s = 1, col: string = C.red) => g(`translate(${x} ${y}) scale(${s})`, circle(-12, 0, 8, 'none', C.ink, 1.8), circle(12, 0, 8, 'none', C.ink, 1.8), path('M-12 0 L-4 -12 L8 -12 L12 0 M-4 -12 L0 0 L8 -12 M0 0 L-12 0', 'none', col, 2), line('M-6 -15 L-2 -15 M6 -14 L10 -16', C.ink, 1.8));
const camera = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, line('M0 0 L0 -6 L-6 -10', C.ink, 1.6), path('M-18 -16 L-2 -16 L-2 -6 L-18 -6 Z', C.white, C.ink, 1.3), circle(-18, -11, 3, C.dark, C.ink, 1), circle(-6, -13, 1.2, RED, null));
const lamp = (x: number, y: number, s = 1, on = true) => g(`translate(${x} ${y}) scale(${s})`, on ? path('M10 -60 L-6 0 L34 0 Z', 'rgba(255,236,140,0.45)', null) : '', line('M0 0 L0 -62 L10 -62', C.dark, 2.4), path('M6 -62 L14 -62 L12 -58 L8 -58 Z', C.yellow, C.ink, 1));
const alarm = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-7 4 C-7 -10 7 -10 7 4 Z', RED, C.ink, 1.3), rect(-9, 4, 18, 3, C.dark, 1, C.ink, 1), path('M-12 -8 L-16 -12 M12 -8 L16 -12 M-13 -1 L-18 -1 M13 -1 L18 -1', 'none', RED, 1.6));
const crowbar = (x: number, y: number, s = 1, rot = 0) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, path('M0 0 L0 -28 C0 -32 4 -33 6 -30', 'none', '#c0392b', 3));
const bench = (x1: number, x2: number, y: number) => all(rect(x1, y, x2 - x1, 26, '#b98a5e', 2, C.ink, 1.6), line(`M${x1} ${y + 6} L${x2} ${y + 6}`, '#8a5f3a', 1.2));
/** The judge behind the bench (a calm person in a dark jacket). */
const judge = (x: number, y: number, s = 1) => mini(x, y, C.dark, 'flat', s);
/** Balance with the beam tilted by `tilt` degrees; pans drawn by l and r. */
const scaleB = (x: number, y: number, tilt: number, l: Svg = '', r: Svg = '', s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-14 40 L14 40 L4 34 L-4 34 Z', C.brown, C.ink, 1.4), line('M0 34 L0 -2', C.ink, 2.6),
  g(`rotate(${tilt})`, line('M-34 0 L34 0', C.ink, 2.6), line('M-32 0 L-40 18 M-32 0 L-24 18 M32 0 L24 18 M32 0 L40 18', C.ink, 1), path('M-44 18 L-20 18 Q-32 26 -44 18 Z', C.gold, C.ink, 1.2), path('M20 18 L44 18 Q32 26 20 18 Z', C.gold, C.ink, 1.2), g('translate(-32 16)', g(`rotate(${-tilt})`, l)), g('translate(32 16)', g(`rotate(${-tilt})`, r))), circle(0, 0, 3, C.gold, C.ink, 1.2));
const flagSE = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, line('M0 0 L0 -26', C.ink, 1.6), rect(0, -26, 18, 11, '#3a6ab0', 0, C.ink, 1), rect(5.5, -26, 3.4, 11, C.yellow, 0, null), rect(0, -22.2, 18, 3.4, C.yellow, 0, null));
/** The parliament: a stone house with columns and the Swedish flag. */
const gov = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-24, -30, 48, 30, '#e8e1d2', 1, C.ink, 1.6), path('M-28 -30 L0 -44 L28 -30 Z', '#cfc6b3', C.ink, 1.6), ...[-16, -6, 4, 14].map((d) => rect(d - 1, -26, 4, 22, C.white, 1, C.ink, 0.9)), rect(-28, -4, 56, 4, '#cfc6b3', 1, C.ink, 1.2), flagSE(0, -44, 0.6));
/** A card showing an act (a small person taking a bag from another person). */
const actIcon = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-16, -14, 32, 28, C.white, 3, C.ink, 1.3), mini(-7, 2, C.dark, 'flat', 0.6), mini(7, 2, PC[1]!, 'shock', 0.6, true), handbag(-1, -3, 0.45, C.red), arrow(4, -8, -6, -8, RED, 1.2));
/** Little crime icons for lists. */
const icoBag = (x: number, y: number, s = 1) => handbag(x, y, 0.7 * s, C.red);
const icoKnife = (x: number, y: number, s = 1) => knife(x - 7 * s, y, 0.6 * s, -20);
const icoCar = (x: number, y: number, s = 1) => car(x, y + 6 * s, 0.4 * s, C.sky);
const icoWin = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-7, -7, 14, 14, '#bfe3f5', 1, C.ink, 1.1), path('M-2 -7 L1 -1 L-3 2 L2 7 M1 -1 L7 -3', 'none', C.ink, 1));
/** Time: an hourglass. */
const hourglass = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-9, -16, 18, 3, C.brown, 1, C.ink, 1), rect(-9, 13, 18, 3, C.brown, 1, C.ink, 1), path('M-7 -13 L7 -13 L1 0 L7 13 L-7 13 L-1 0 Z', 'rgba(220,240,252,0.7)', C.ink, 1.2), path('M-4 -9 L4 -9 L0 -2 Z M-5 13 L5 13 L0 7 Z', C.yellow, null));
/** A row of tally marks (days in prison). */
const tally = (x: number, y: number, n: number, s = 1) => all(...Array.from({ length: n }, (_, i) => line(`M${f1(x + i * 4 * s + Math.floor(i / 5) * 4 * s)} ${y} L${f1(x + i * 4 * s + Math.floor(i / 5) * 4 * s)} ${f1(y + 10 * s)}`, C.ink, 1.3)));
/** A time bar of n segments where the first `done` are filled. */
const tbar = (x: number, y: number, w: number, n: number, done: number, col: string = HL) => all(...Array.from({ length: n }, (_, i) => rect(x + (w / n) * i, y, w / n - 1.5, 8, i < done ? col : C.white, 1.5, C.ink, 1.1)));
